//! Tables of multiples of the base point G. The data lives in `precomp_data.rs`, generated by
//! the test below; that test also recomputes it from G with the regular point arithmetic, so
//! every test run proves that the table is right.

use super::curve::Affine;

/// Width of the signed windows used for fixed-base multiplication.
pub(crate) const COMB_WIDTH: usize = 5;
/// Windows needed for any 256-bit scalar: the recoding may carry into bit 256.
pub(crate) const COMB_WINDOWS: usize = 256 / COMB_WIDTH + 1;
/// Magnitudes 1..=2^(width-1) in each window.
pub(crate) const COMB_ENTRIES: usize = 1 << (COMB_WIDTH - 1);

/// `G_ODD[i]` = (2i + 1) G, for wNAF of width `G_ODD_WIDTH` in public-scalar multiplication.
pub(crate) const G_ODD_WIDTH: usize = 8;
pub(crate) const G_ODD_ENTRIES: usize = 1 << (G_ODD_WIDTH - 2);

/// Table entry from x and y limbs.
const fn e(x: [u64; 4], y: [u64; 4]) -> Affine {
    Affine { x, y }
}

include!("precomp_data.rs");

#[cfg(test)]
mod tests {
    use super::super::curve::normalize_batch;
    use super::super::point::{SM2_GX, SM2_GY};
    use super::*;
    use std::fmt::Write;

    const G: Affine = Affine {
        x: SM2_GX.value.limbs,
        y: SM2_GY.value.limbs,
    };

    /// `comb[w][m - 1]` = m * 2^(COMB_WIDTH * w) * G
    fn compute_comb() -> Vec<Vec<Affine>> {
        let mut comb = Vec::new();
        let mut base = G.to_jacobian();
        for _ in 0..COMB_WINDOWS {
            let mut row = [base; COMB_ENTRIES];
            for m in 1..COMB_ENTRIES {
                row[m] = row[m - 1].add_vartime(&base);
            }
            comb.push(normalize_batch(&row).to_vec());
            for _ in 0..COMB_WIDTH {
                base = base.double();
            }
        }
        comb
    }

    fn compute_odd() -> [Affine; G_ODD_ENTRIES] {
        let twice = G.to_jacobian().double();
        let mut odd = [G.to_jacobian(); G_ODD_ENTRIES];
        for i in 1..G_ODD_ENTRIES {
            odd[i] = odd[i - 1].add_vartime(&twice);
        }
        normalize_batch(&odd)
    }

    #[test]
    fn tables_match_recomputation() {
        let comb = compute_comb();
        for (window, row) in comb.iter().enumerate() {
            for (m, entry) in row.iter().enumerate() {
                assert_eq!(G_COMB[window][m].x, entry.x, "comb {window} {m}");
                assert_eq!(G_COMB[window][m].y, entry.y, "comb {window} {m}");
            }
        }
        for (i, entry) in compute_odd().iter().enumerate() {
            assert_eq!(G_ODD[i].x, entry.x, "odd {i}");
            assert_eq!(G_ODD[i].y, entry.y, "odd {i}");
        }
    }

    fn entry_text(out: &mut String, point: &Affine) {
        let limbs = |l: &[u64; 4]| {
            format!(
                "[{:#018x}, {:#018x}, {:#018x}, {:#018x}]",
                l[0], l[1], l[2], l[3]
            )
        };
        writeln!(
            out,
            "    e({},\n      {}),",
            limbs(&point.x),
            limbs(&point.y)
        )
        .unwrap();
    }

    /// Prints the contents of `precomp_data.rs`:
    /// `cargo test --lib print_tables -- --ignored --nocapture`, between the marker lines.
    #[test]
    #[ignore = "generator for precomp_data.rs"]
    fn print_tables() {
        let mut out = String::from(
            "// @generated by the `print_tables` test in precomp.rs. Do not edit.\n\n\
             #[rustfmt::skip]\n\
             pub(crate) static G_COMB: [[Affine; COMB_ENTRIES]; COMB_WINDOWS] = [\n",
        );
        for row in compute_comb() {
            out.push_str("  [\n");
            for point in &row {
                entry_text(&mut out, point);
            }
            out.push_str("  ],\n");
        }
        out.push_str(
            "];\n\n#[rustfmt::skip]\npub(crate) static G_ODD: [Affine; G_ODD_ENTRIES] = [\n",
        );
        for point in &compute_odd() {
            entry_text(&mut out, point);
        }
        out.push_str("];\n");
        println!("=====BEGIN=====\n{out}=====END=====");
    }
}
